  "deepseek-v4.1-flash"
],

// Start the installed protocol adapter without its CLI's global config injection.
// Configuration and credentials belong to this isolated desktop router only.
const gate = createReadinessGate();
const server = startServer(10102, { readinessGate: gate });
Bun.serve = originalServe;
console.log(`Desktop model router listening on 127.0.0.1:${server.port}`);
// No Codex config/catalog synchronization runs in this standalone adapter host.
gate.markReady();

let reasoningContent = thinkingParts.map(p => p.thinking).join("");
// History transformations (compaction, lost assistant turn, resumed
// threads) can strip the reasoning item while the tool round survives.
// Re-attach the reasoning the bridge recorded for these call ids so
// preserveReasoningContentModels providers (DeepSeek thinking mode)
// never receive a bare tool-call continuation (issue #950).
if (
  reasoningContent.length === 0
  && toolCalls.length > 0
  && modelInList(provider.preserveReasoningContentModels, parsed.modelId)
) {
  const cached = toolCalls
    .map(tc => (tc.id ? peekReasoningForCall(tc.id, replayCacheScope) : undefined))
    .filter((text): text is string => typeof text === "string" && text.length > 0);
  // Parallel calls share one preceding reasoning block, which is
  // recorded under every call id — join unique texts only.
  if (cached.length > 0) {
    reasoningContent = [...new Set(cached)].join("\n");
  }
}
if (reasoningContent.length > 0 && modelInList(provider.preserveReasoningContentModels, parsed.modelId)) {
  chatMsg.reasoning_content = reasoningContent;
}

// 0. Explicit "<provider>/<model>" namespace (e.g. "opencode-go/deepseek-v4-pro").
//    Only triggers when the prefix matches a CONFIGURED provider, so genuine
//    slash-containing model ids (e.g. "anthropic/claude-...") fall through when
//    no such provider exists.
if (slash > 0) {
  const provName = modelId.slice(0, slash);
  if (provName === LEGACY_CHATGPT_PROVIDER_ID || provName === LEGACY_OPENAI_MULTI_PROVIDER_ID) {
    throw new Error(`No provider configured for model: ${modelId}`);
  }
  if (hasOwnProvider(config.providers, provName)) {
    const prov = config.providers[provName];
    if (prov.disabled === true) throw new Error(`Provider is disabled: ${provName}`);
    const known = knownModelIdsForProvider(provName, prov);
    // Self-namespaced native id — the vendor segment equals the provider id, so the FULL ref is
    // itself a known model (e.g. orcarouter/auto). Route it whole instead of stripping to the
    // remainder, which would send a bare `auto` the upstream cannot resolve.
    if (known.includes(modelId)) {
      return routeResult(provName, prov, modelId, "explicit-provider", "explicit-provider-namespace");
    }
    // Codex-facing alias ids (`provider/vendor-model`) decode back to the native
    // slash id via an exact known-id lookup; raw full-slash selectors keep working.
    return routeResult(
      provName,
      prov,
      decodeRoutedModelId(modelId.slice(slash + 1), known),
      "explicit-provider",
      "explicit-provider-namespace",
    );

if (config.defaultProvider === LEGACY_CHATGPT_PROVIDER_ID) {
  throw new Error(`No provider configured for model: ${modelId}`);
}
if (hasOwnProvider(config.providers, config.defaultProvider)) {
  const defaultProv = config.providers[config.defaultProvider];
  if (defaultProv.disabled === true) throw new Error(`Default provider is disabled: ${config.defaultProvider}`);
  return routeResult(config.defaultProvider, defaultProv, modelId, "default-provider", "default-provider");
}

throw new Error(`No provider configured for model: ${modelId}`);

// WS transport gate: Codex's built-in `openai` provider hardcodes supports_websockets=true,
// so under Design B it always tries the WS transport first. When the feature is off, reject
// the upgrade with 426 — codex-rs maps a connect-time UPGRADE_REQUIRED to a clean
// session-scoped HTTP fallback (client.rs WebsocketStreamOutcome::FallbackToHttp) instead of
// surfacing broken-pipe errors from sockets a "disabled" feature would otherwise accept.
if (!websocketsEnabled(config)) {
  return withCors(formatErrorResponse(426, "upgrade_required", "Responses WebSocket transport is disabled; use HTTP"), req, policy);
}
